import json,pathlib
from markdown_it import MarkdownIt
inv=[x for x in json.load(open('/work/inventory.json')) if x['ref'].startswith('d')]
inv.sort(key=lambda x:int(x['path'].split('-')[-1].split('.')[0]))
md=MarkdownIt('commonmark')
a=[]
for x in inv:
 s=pathlib.Path('/work',x['path']).read_text()
 for t in md.parse(s):
  if t.type=='inline':
   j=0
   for c in t.children:
    if c.type=='link_open':
     j+=1
     if c.attrGet('href').split('#')[0]=='repa:document/dd97fe15282':
      a.append(f"{x['ref']}@{t.map[0]+1}:{j}")
      print(a[-1],repr(t.content))
print('ANSWERS',json.dumps(a)); print('DOCS',len(inv))
print('--- ALL TARGET SOURCE ---')
for x in inv:
 s=pathlib.Path('/work',x['path']).read_text()
 if 'dd97fe15282' in s:
  print(x['ref'],x['path']); print(s)
PY

