python3 - <<'PY'
import json,sqlite3,pathlib
base=pathlib.Path('/work');inv={o['ref']:o for o in json.load(open(base/'inventory.json'))}
c=sqlite3.connect('file:/work/learning.sqlite?mode=ro',uri=True)
refs=[r[0] for r in c.execute('SELECT a.question_ref FROM attempts a WHERE a.correct=0 AND a.seq=(SELECT MAX(b.seq) FROM attempts b WHERE b.question_ref=a.question_ref) ORDER BY a.question_ref')]
hits=[];unresolved=[]
for ref in refs:
 try:
  text=(base/inv[ref]['path']).read_text()
  if '写回路径' in text:
   hits.append(ref);print(ref,repr(text))
 except Exception as e:unresolved.append(ref)
print(json.dumps({'answers':sorted(set(hits))[:3],'unresolved':unresolved},ensure_ascii=False))
print('scope',len(refs),'hits',len(hits))
PY

python3 - <<'PY'
import json,sqlite3,pathlib
b=pathlib.Path('/work'); inv={o['ref']:o for o in json.load(open(b/'inventory.json'))};c=sqlite3.connect('file:/work/learning.sqlite?mode=ro',uri=True)
h=[];u=[]
for (r,) in c.execute('SELECT DISTINCT a.question_ref FROM attempts a WHERE correct=0 AND seq=(SELECT MAX(seq) FROM attempts b WHERE b.question_ref=a.question_ref)'):
 try:
  if '写回路径' in (b/inv[r]['path']).read_text():h.append(r)
 except Exception:u.append(r)
print(json.dumps({'answers':sorted(set(h))[:3],'unresolved':sorted(u)}))
PY

