import sqlite3,json,pathlib
c=sqlite3.connect('/work/learning.sqlite')
rows=c.execute('select * from attempts order by question_ref,seq').fetchall()
print('ATTEMPTS',rows)
i={x['ref']:x for x in json.load(open('/work/inventory.json'))}
latest={}
for row in rows:latest[row[1]]=row
for ref,r in sorted(latest.items()):
 if r[3]==0:
  obj=i.get(ref); print('\nWRONG',r,obj)
  if obj and 'path' in obj:
   try:print(pathlib.Path('/work',obj['path']).read_text())
   except Exception as e:print(type(e).__name__)
