python3 - <<'PY'
import sqlite3,json,pathlib
c=sqlite3.connect('/work/learning.sqlite')
i={o['ref']:o for o in json.load(open('/work/inventory.json'))}
refs=[r[0] for r in c.execute('select question_ref from attempts a where correct=0 and seq=(select max(seq) from attempts b where b.question_ref=a.question_ref)')]
found=set(); unresolved=[]
for ref in refs:
 try:
  t=pathlib.Path('/work',i[ref]['path']).read_text()
  if '写回路径' in t:found.add(ref)
 except Exception:unresolved.append(ref)
print('wrong_count',len(refs),'match_count',len(found))
print(json.dumps({'answers':sorted(found)[:3],'unresolved':unresolved},ensure_ascii=False))
for ref in sorted(found)[:3]:
 print(ref,i[ref]['path'],[l for l in pathlib.Path('/work',i[ref]['path']).read_text().splitlines() if '写回路径' in l])
