print('wrong',len(refs))
inv=json.load(open('/work/inventory.json'))
for o in inv:
 if o['ref'] in refs:
  p=pathlib.Path('/work')/o.get('path','')
  print('\nOBJECT',o)
  try: print(p.read_text())
  except Exception as e: print(e)
print('not in inventory',refs-{o['ref'] for o in inv})
