import sqlite3,json,pathlib
c=sqlite3.connect('/work/learning.sqlite');c.row_factory=sqlite3.Row
rs=c.execute('''select e.*,a.seq,a.correct from experiments e join attempts a on a.question_ref=e.note_ref where e.dataset='cpu' and e.valid=1 and a.correct=0 and a.seq=(select max(b.seq) from attempts b where b.question_ref=a.question_ref) order by e.latency_us,e.id''').fetchall()
print([dict(r) for r in rs])
i=json.load(open('/work/inventory.json')); print('inventory type',type(i).__name__)
if isinstance(i,dict): print(list(i.keys()))
else:
 for o in i:
  if o['ref']==rs[0]['note_ref']:
   print(o);print(pathlib.Path('/work',o['path']).read_text())
