import json,sqlite3,pathlib,re
inv={v['ref']:v for v in json.load(open('/work/inventory.json'))}
c=sqlite3.connect('/work/learning.sqlite');ans=[];un=[]
for (r,) in c.execute('select question_ref from attempts a where correct=0 and seq=(select max(seq) from attempts b where b.question_ref=a.question_ref) order by question_ref'):
 try:s=pathlib.Path('/work',inv[r]['path']).read_text()
 except Exception:un.append(r);continue
 if '写回路径' in s:
  print(r, [l for l in s.splitlines() if '写回路径' in l])
  ans.append(r+'='+re.search(r'校验词：(\S+)',s).group(1))
print(json.dumps({'answers':ans,'unresolved':un},ensure_ascii=False,indent=2))
