import json,pathlib,posixpath
from markdown_it import MarkdownIt
from html.parser import HTMLParser
from urllib.parse import urlsplit,unquote
inv=json.load(open('/work/inventory.json')); objs=sorted([o for o in inv if o['ref'].startswith('d')],key=lambda o:int(o['path'].split('-')[-1][:-3])); paths={o.get('path'):o['ref'] for o in inv}
class A(HTMLParser):
 def __init__(self): super().__init__(); self.links=[]
 def handle_starttag(self,tag,attrs):
  if tag=='a' and 'href' in dict(attrs): self.links.append(dict(attrs)['href'])
md=MarkdownIt('commonmark'); answers=[]; unresolved=[]
for o in objs:
 try: s=pathlib.Path('/work',o['path']).read_text()
 except (OSError,UnicodeError): unresolved.append(o['ref']);continue
 for t in md.parse(s):
  hrefs=[]
  if t.type=='inline':
   for c in t.children:
    if c.type=='link_open':hrefs.append(c.attrGet('href'))
    elif c.type=='html_inline':
     a=A();a.feed(c.content);hrefs.extend(a.links)
  elif t.type=='html_block':
   a=A();a.feed(t.content);hrefs.extend(a.links)
  if hrefs:
   print(o['ref'],t.map,repr(t.content),hrefs)
  for n,h in enumerate(hrefs,1):
   u=urlsplit(h)
   if u.scheme=='repa': target=u.path.removeprefix('document/')
   elif not u.scheme and not u.netloc:target=paths.get(posixpath.normpath(posixpath.join(posixpath.dirname(o['path']),unquote(u.path)))) if u.path else o['ref']
   else:target=None
   if target=='d7bd6899029':answers.append(f"{o['ref']}@{t.map[0]+1}:{n}")
print('TOTAL OBJECTS',len(objs))
print(json.dumps({'answers':answers,'unresolved':unresolved},ensure_ascii=False,indent=2))
