from pathlib import Path
from markdown_it import MarkdownIt
from urllib.parse import unquote,urlsplit
import posixpath
root=Path('/work'); targets={'docs/adr/0002-progressively-load-learning-context.md','docs/adr/0003-share-file-based-content-operations.md'}
for p in sorted(root.rglob('*.md')):
 links=[]
 def walk(ts):
  for t in ts:
   if t.type=='link_open':
    href=t.attrGet('href'); u=urlsplit(href)
    if not u.scheme and not u.netloc:
     dest=posixpath.normpath(posixpath.join(str(p.relative_to(root).parent),unquote(u.path))) if not u.path.startswith('/') else u.path.lstrip('/')
     if dest in targets: links.append((href,dest))
   if t.children: walk(t.children)
 walk(MarkdownIt().parse(p.read_text()))
 if targets.issubset({d for _,d in links}): print(str(p.relative_to(root)),links)
