python3 - <<'PY'
import json,pathlib,posixpath
from markdown_it import MarkdownIt
from html.parser import HTMLParser
from urllib.parse import urlsplit,unquote
p=pathlib.Path('/work'); inv={x['ref']:x for x in json.loads((p/'inventory.json').read_text())}; paths={x.get('path'):x['ref'] for x in inv.values() if 'path'in x}; md=MarkdownIt('commonmark')
class A(HTMLParser):
 def __init__(self):super().__init__();self.links=[]
 def handle_starttag(self,tag,attrs):
  if tag=='a':
   for k,v in attrs:
    if k=='href':self.links.append(v);break
 def handle_startendtag(self,tag,attrs):self.handle_starttag(tag,attrs)
def html_links(s):
 a=A();a.feed(s);return a.links
ans=[];unresolved=[]
for r in json.loads((p/'reference-scope.json').read_text()):
 o=inv[r]
 try:s=(p/o['path']).read_text()
 except Exception:unresolved.append(r);continue
 ts=md.parse(s)
 for t in ts:
  links=[]
  if t.type=='inline':
   for c in t.children:
    if c.type=='link_open':links.append(c.attrGet('href'))
    elif c.type=='html_inline':links+=html_links(c.content)
  elif t.type=='html_block':links+=html_links(t.content)
  for i,l in enumerate(links,1):
   u=urlsplit(l)
   dest=l.split('#')[0] if u.scheme=='repa' else paths.get(posixpath.normpath(posixpath.join(posixpath.dirname(o['path']),unquote(u.path)))) if not u.scheme else None
   match=dest in ('repa:document/d0bb9bb1bed','d0bb9bb1bed')
   print(r,t.map[0]+1,i,repr(l),match,repr(t.content[:180]))
   if match:ans.append(f'{r}@{t.map[0]+1}:{i}')
print('RESULT',json.dumps({'answers':ans,'unresolved':unresolved}))
PY

