arguments.command:
python3 - <<'PY'
import json,sqlite3,os
inv=json.load(open('/work/inventory.json'))
db=sqlite3.connect('/work/learning.sqlite')
wrong=db.execute('''select a.question_ref,a.seq,a.correct from attempts a join (select question_ref,max(seq) seq from attempts group by question_ref) m using(question_ref,seq) where a.correct=0''').fetchall()
print('WRONG',len(wrong),wrong)
wrongrefs={r[0] for r in wrong}
for x in inv:
 if x['ref'] in wrongrefs:
  print('wrongdoc',x)
# scan docs content literal phrase
anns=[json.loads(l) for l in open('/work/annotations.jsonl')]
byid={a.get('id'):a for a in anns}
hits=[]
for x in inv:
 content=''
 if 'path' in x:
  try: content=open('/work/'+x['path']).read()
  except: continue
 elif x['kind']=='record': content=json.dumps(byid.get(x['key']),ensure_ascii=False)
 if '写回路径' in content:
  hits.append((x['ref'],x['kind'],x.get('path'),x.get('key'),content[:350]))
print('HITS',len(hits))
for h in hits: print(h)
print('INTERSECTION')
for h in hits:
 if h[0] in wrongrefs: print(h[:4])
PY

python3 - <<'PY'
import json,sqlite3,re,os
inv=json.load(open('/work/inventory.json')); db=sqlite3.connect('/work/learning.sqlite')
wrong={r[0] for r in db.execute('''select a.question_ref from attempts a join (select question_ref,max(seq) seq from attempts group by question_ref) m using(question_ref,seq) where a.correct=0''')}
for x in inv:
 if x['ref'] not in wrong or x['kind'] not in ('markdown','html'): continue
 try: s=open('/work/'+x['path']).read()
 except: continue
 if '写回路径' in s:
  print(x['ref'], re.search(r'校验词：([^\r\n]+)',s).group(1) if re.search(r'校验词：([^\r\n]+)',s) else 'NO_TOKEN', x['path'])
