import json,os,urllib.parse
from markdown_it import MarkdownIt
from html.parser import HTMLParser
root='/work'; scope=set(json.load(open(root+'/reference-scope.json'))); inv=json.load(open(root+'/inventory.json')); byref={x['ref']:x for x in inv}; bypath={os.path.normpath(x['path']):x['ref'] for x in inv if 'path' in x}
target='d0bb9bb1bed'
def html_hrefs(s):
 class P(HTMLParser):
  def __init__(self): super().__init__(); self.hs=[]
  def handle_starttag(self,tag,attrs):
   if tag.lower()=='a':
    d=dict(attrs)
    if 'href' in d: self.hs.append(d['href'])
 p=P(); p.feed(s); return p.hs

def dest_ref(dest, sourcepath):
 d=dest.strip()
 # CommonMark autolink/link destination direct value
 if d.startswith('repa:document/'):
  return d[len('repa:document/'):].split('#',1)[0].split('?',1)[0]
 u=urllib.parse.urlsplit(d)
 if u.scheme or u.netloc: return None
 path=urllib.parse.unquote(u.path)
 if not path: return None
 resolved=os.path.normpath(os.path.join(os.path.dirname(sourcepath),path))
 return bypath.get(resolved)
md=MarkdownIt('commonmark')
results=[]
for ref in scope:
 o=byref.get(ref)
 if not o or o.get('kind')!='markdown': continue
 path=o['path']; full=os.path.join(root,path)
 try: src=open(full).read()
 except: continue
 toks=md.parse(src)
 i=0
 while i<len(toks):
  t=toks[i]
  if t.nesting==1 and t.level==0:
   typ=t.type; start=t.map[0]+1 if t.map else 1
   # locate matching close of same top-level block; inline tokens between
   depth=1; j=i+1; group=[]
   while j<len(toks):
    q=toks[j]
    if q.level==0:
     if q.nesting==1: depth+=1
     elif q.nesting==-1:
      depth-=1
      if depth==0: break
    group.append(q); j+=1
   links=[]
   for q in group:
    if q.type=='inline':
     for c in q.children or []:
      if c.type=='link_open': links.append(('md',c.attrGet('href')))
      elif c.type=='html_inline': links += [('html',h) for h in html_hrefs(c.content)]
    elif q.type=='html_block': links += [('html',h) for h in html_hrefs(q.content)]
   for n,(kind,dest) in enumerate(links,1):
    if dest is not None and dest_ref(dest,path)==target:
     results.append((ref,start,n,kind,dest,path,typ))
   i=j+1
  else:
   # standalone non-nesting blocks eg fenced code no links, html_block possibly top-level
   if t.type=='html_block':
    start=t.map[0]+1 if t.map else 1
    for n,dest in enumerate(html_hrefs(t.content),1):
     if dest_ref(dest,path)==target: results.append((ref,start,n,'html',dest,path,t.type))
   i+=1
for x in sorted(results):print('@'.join(map(str,x[:3])),x[3:])
print('COUNT',len(results))
