from agent_data_lab.native import markdown_links
inv=json.load(open('/work/inventory.json')); scope=set(json.load(open('/work/reference-scope.json')))
byref={o['ref']:o for o in inv}; bypath={str(pathlib.Path(o['path']).as_posix()):o for o in inv if 'path'in o}
target='d0bb9bb1bed'
for ref in json.load(open('/work/reference-scope.json')):
 o=byref.get(ref)
 if not o or o['kind']!='markdown': continue
 p=pathlib.Path('/work')/o['path']; txt=p.read_text()
 for l in markdown_links(txt):
  u=l['uri']; hit=False
  if u.startswith('repa:document/'):
   val=urllib.parse.unquote(u[len('repa:document/'):].split('#',1)[0])
   hit=val==target
  else:
   # strip query/fragment; resolve from source file
   val=urllib.parse.unquote(u.split('#',1)[0].split('?',1)[0])
   if val:
    dest=(p.parent/val).resolve()
    hit=dest==((pathlib.Path('/work')/byref[target]['path']).resolve())
  if hit: print(ref, l)
