import json,pathlib,posixpath
from markdown_it import MarkdownIt
from html.parser import HTMLParser
from urllib.parse import urlsplit,unquote
p=pathlib.Path('/work'); inv={v['ref']:v for v in json.loads((p/'inventory.json').read_text())}; paths={v.get('path'):v['ref'] for v in inv.values() if 'path' in v}; md=MarkdownIt('commonmark')
class A(HTMLParser):
 def __init__(self):super().__init__();self.links=[]
 def handle_starttag(self,t,a):
  if t=='a':
   for k,v in a:
    if k=='href':self.links.append(v);break
 def handle_startendtag(self,t,a):self.handle_starttag(t,a)
def html(s):
 a=A();a.feed(s);return a.links
ans=[];unresolved=[]
for r in json.loads((p/'reference-scope.json').read_text()):
 try:
  v=inv[r];s=(p/v['path']).read_text(); ts=md.parse(s)
 except Exception as e:unresolved.append(r);continue
 for t in ts:
  links=[]
  if t.type=='inline':
   for c in t.children:
    if c.type=='link_open':links.append(c.attrGet('href'))
    if c.type=='html_inline':links.extend(html(c.content))
  elif t.type=='html_block':links=html(t.content)
  for i,u in enumerate(links,1):
   if u.startswith('repa:document/'): dest=u[len('repa:document/'):].split('#')[0]
   else:
    parsed=urlsplit(u); dest=paths.get(posixpath.normpath(posixpath.join(posixpath.dirname(v['path']),unquote(parsed.path)))) if not parsed.scheme and not parsed.netloc else None
   print(r,t.map[0]+1,i,repr(u),'MATCH' if dest=='d6527686060' else 'OTHER',repr(t.content[:180]))
   if dest=='d6527686060':ans.append(f'{r}@{t.map[0]+1}:{i}')
print(json.dumps({'answers':ans,'unresolved':unresolved},ensure_ascii=False,indent=2))
