import json,os,posixpath,re,html
from markdown_it import MarkdownIt
from html.parser import HTMLParser
inv=json.load(open('/work/inventory.json')); scope=json.load(open('/work/reference-scope.json'))
byref={x['ref']:x for x in inv}; bypath={x['path']:x['ref'] for x in inv if 'path' in x}
target='d6527686060'; targetpath=byref[target]['path']
class A(HTMLParser):
 def __init__(self): super().__init__(); self.href=[]
 def handle_starttag(self,tag,attrs):
  if tag.lower()=='a':
   d=dict(attrs)
   if 'href' in d:self.href.append(d['href'])
def resolve(href,path):
 href=html.unescape(href.strip())
 if href.startswith('repa:document/'):
  return href[len('repa:document/'):].split('#')[0]
 # normalize relative path, remove fragment/query
 p=href.split('#')[0].split('?')[0]
 if not p or p.startswith(('http:','https:','mailto:','//','#')):return None
 cand=posixpath.normpath(posixpath.join(posixpath.dirname(path),p))
 return bypath.get(cand)
md=MarkdownIt('commonmark',{'html':True})
out=[]
for ref in scope:
 x=byref[ref]
 if x.get('kind')!='markdown':continue
 path=x['path']; s=open('/work/'+path).read(); toks=md.parse(s)
 # block records (map, inline) and html blocks; possible block nesting map; process blocks independently based on inline block map
 blocks=[]
 for t in toks:
  if t.type=='inline' and t.map:
   links=[]
   for c in t.children or []:
    if c.type=='link_open':
     href=dict(c.attrs or []).get('href'); links.append(href)
    elif c.type=='html_inline':
     a=A(); a.feed(c.content); links.extend(a.href)
   blocks.append((t.map[0]+1,links))
  elif t.type=='html_block' and t.map:
   a=A(); a.feed(t.content); blocks.append((t.map[0]+1,a.href))
 for line,links in blocks:
  for idx,h in enumerate(links,1):
   if resolve(h,path)==target: out.append((ref,line,idx,h,path))
print('\n'.join(map(str,out)))
print('count',len(out))
