import json,sqlite3,re
inv=json.load(open('inventory.json')); c=sqlite3.connect('learning.sqlite')
wrong=set()
for ref,seq in c.execute('select question_ref,max(seq) from attempts group by question_ref'):
 correct=c.execute('select correct from attempts where question_ref=? and seq=?',(ref,seq)).fetchone()[0]
 if correct==0: wrong.add(ref)
for x in inv:
 if x['ref'] in wrong and x['kind'] in ('markdown','html'):
  txt=open(x['path'],encoding='utf-8').read()
  if '写回路径' in txt:
   m=re.search(r'校验词：([^\s]+)',txt)
   print(x['ref']+'='+m.group(1) if m else 'NO TOKEN '+x['ref'])
